insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_64_v1'
from (values
('127.409.d.1',3,'A materials engineer finds that a batch of steel bolts failed a strength test but the shipment is due today. The ethical action is to:','["report the failure and hold the shipment", "ship it anyway", "change the test result", "hide the report"]'::jsonb,0,'Safety outranks deadlines.','original'),
('127.409.d.1',4,'Signing off on a test report for steel that was never tested would be:','["good practice", "a violation of professional ethics", "a time saver", "required by law"]'::jsonb,1,'Engineers must be honest about their work.','original'),
('127.409.d.2.A',3,'A student notices that a metal ruler bends more than a wooden one of the same size and asks why. This is a question based on:','["a unit", "a grade", "observation", "a map"]'::jsonb,2,'Investigations start with observations.','original'),
('127.409.d.2.A',4,'''Find which of three metals resists bending best under a 10 N load'' is a well-defined problem because it names a:','["color", "slogan", "feeling", "measurable comparison"]'::jsonb,3,'Testable problems are measurable.','original'),
('127.409.d.2.B',3,'Testing three metal strips by hanging the same weight on each and measuring the bend is a comparative investigation because it:','["compares materials under equal conditions", "avoids measuring", "tests only one strip", "uses no weight"]'::jsonb,0,'Fair comparisons control conditions.','original'),
('127.409.d.2.B',4,'In a bending experiment, the weight that the investigator chooses to change is the:','["hypothesis", "independent variable", "dependent variable", "constant"]'::jsonb,1,'The independent variable is manipulated.','original'),
('127.409.d.2.C',3,'Before running a tensile test machine, a student should confirm that a protective shield is:','["painted", "missing", "in place", "removed"]'::jsonb,2,'Guards protect against flying fragments.','original'),
('127.409.d.2.C',4,'Metal specimens with sharp edges are best handled while wearing:','["sandals", "earbuds", "a scarf", "cut-resistant gloves and safety glasses"]'::jsonb,3,'PPE matches the hazard.','original'),
('127.409.d.2.D',3,'A micrometer is chosen over a ruler to measure the thickness of a metal sheet because it:','["reads much smaller increments", "weighs more", "is longer", "is cheaper"]'::jsonb,0,'Micrometers are precise.','original'),
('127.409.d.2.D',4,'A protractor is the correct tool for measuring the:','["temperature of steel", "angle of a bent bracket", "mass of a bolt", "density of wood"]'::jsonb,1,'Protractors measure angles.','original'),
('127.409.d.2.E',3,'A steel rod is 0.5 meters long. In millimeters, this is:','["50 mm", "5,000 mm", "500 mm", "5 mm"]'::jsonb,2,'0.5 x 1,000 = 500.','original'),
('127.409.d.2.E',4,'A load of 2,000 newtons is written in kilonewtons as:','["200 kN", "0.2 kN", "20 kN", "2 kN"]'::jsonb,3,'1 kN = 1,000 N.','original'),
('127.409.d.2.F',3,'A spreadsheet column of load readings in newtons paired with extension readings in millimeters is an example of organized:','["quantitative data", "opinions", "qualitative notes", "rumors"]'::jsonb,0,'Measured numbers are quantitative.','original'),
('127.409.d.2.F',4,'A written note that a fractured steel sample surface ''looks rough and gray'' is:','["quantitative data", "qualitative data", "a calculation", "a unit conversion"]'::jsonb,1,'Descriptions are qualitative.','original'),
('127.409.d.2.G',3,'A scale drawing of a truss bridge used to explain how loads travel through it is a:','["unit", "theory", "model", "law"]'::jsonb,2,'Drawings model systems.','original'),
('127.409.d.2.G',4,'A computer model of a beam under load can predict where it will:','["be named", "be painted", "be sold", "bend most"]'::jsonb,3,'Simulations predict behavior.','original'),
('127.409.d.2.H',3,'A well-tested description that metals expand when heated, summarized in a formula, is most like a:','["scientific law", "rumor", "opinion", "wild guess"]'::jsonb,0,'Laws describe repeatable patterns.','original'),
('127.409.d.2.H',4,'A statement such as ''This alloy will bend less than that one'' is a testable prediction called a:','["law", "hypothesis", "unit", "summary"]'::jsonb,1,'A hypothesis can be tested.','original'),
('127.409.d.3.A',3,'A small-scale model of a bridge may not predict real failure loads because the model cannot always match:','["a spreadsheet", "a ruler", "the full-size structure", "a book"]'::jsonb,2,'Scale effects limit models.','original'),
('127.409.d.3.A',4,'A computer simulation of a beam is faster than building one but depends on the correctness of its:','["title", "color", "font", "input assumptions"]'::jsonb,3,'Models are only as good as their inputs.','original'),
('127.409.d.3.B',3,'A graph of load against stretch for a spring is a straight line. This pattern tells the analyst that stretch is:','["proportional to load", "unrelated to load", "constant", "random"]'::jsonb,0,'Straight lines through the origin show proportionality.','original'),
('127.409.d.3.B',4,'An analyst finds one test result far from the other nine and should first:','["erase it silently", "check whether it is a measurement error", "double it", "ignore all data"]'::jsonb,1,'Outliers need investigation.','original'),
('127.409.d.3.C',3,'A bar of cross-sectional area 4 cm2 carries 8,000 N. The stress is:','["32,000 N/cm2", "500 N/cm2", "2,000 N/cm2", "2 N/cm2"]'::jsonb,2,'Stress = force / area = 8,000 / 4.','original'),
('127.409.d.3.C',4,'If the same load acts on a bar with twice the area, the stress becomes:','["twice as large", "four times as large", "unchanged", "half as large"]'::jsonb,3,'Stress is inversely proportional to area.','original'),
('127.409.d.3.D',3,'A test shows a new aluminum bracket bends too much under its design load. Evaluating the design means comparing the result to the:','["design criteria", "lunch order", "price tag", "paint choices"]'::jsonb,0,'Evaluation compares data to criteria.','original'),
('127.409.d.3.D',4,'A good design test changes one factor at a time so the engineer can:','["hide results", "tell which change caused the result", "skip analysis", "avoid data"]'::jsonb,1,'Controlled tests isolate causes.','original'),
('127.409.d.4.A',3,'A claim that thicker beams deflect less is best supported by:','["a rumor", "a poster", "measured deflection data", "a guess"]'::jsonb,2,'Evidence supports claims.','original'),
('127.409.d.4.A',4,'Proposing to add a rib to a weak bracket should be backed by a model or test showing that the rib:','["shortens the name", "adds color", "lowers the price tag", "reduces bending"]'::jsonb,3,'Solutions must be justified.','original'),
('127.409.d.4.B',3,'A team shows its test results with a graph, a table, and a short explanation. This is communicating:','["with multiple formats", "with no data", "in secret", "by rumor"]'::jsonb,0,'Several formats help audiences.','original'),
('127.409.d.4.B',4,'Reports of material tests should state values with their:','["jokes", "units", "nicknames", "slogans"]'::jsonb,1,'Numbers need units.','original'),
('127.409.d.4.C',3,'A respectful scientific argument about which alloy is stronger relies on:','["personal attacks", "loud voices", "evidence from tests", "popularity"]'::jsonb,2,'Argue with evidence.','original'),
('127.409.d.4.C',4,'When a teammate challenges your stress calculation, a respectful response is to:','["walk away", "insult back", "ignore them", "recheck the work and explain the steps"]'::jsonb,3,'Open discussion improves accuracy.','original'),
('127.409.d.5.A',3,'To critique a claim that a new alloy is ''twice as strong,'' check whether the claim is backed by:','["controlled test data", "bright packaging", "advertising", "a famous name"]'::jsonb,0,'Evaluate the evidence.','original'),
('127.409.d.5.A',4,'A conclusion drawn from only one specimen of a material is weak because specimens vary, so the result may be:','["legal", "unrepresentative", "permanent", "certain"]'::jsonb,1,'One sample may not reflect the batch.','original'),
('127.409.d.5.B',3,'The development of steel-reinforced concrete changed construction by allowing:','["no buildings", "smaller buildings only", "taller, longer-spanning structures", "wooden bridges only"]'::jsonb,2,'Reinforcement adds tensile strength.','original'),
('127.409.d.5.B',4,'Research into carbon fiber has changed aircraft design by providing materials that are strong and:','["heavy", "brittle only", "weak", "lightweight"]'::jsonb,3,'Composites save weight.','original'),
('127.409.d.5.C',3,'A museum of science and industry can help a student learn how engineers used:','["materials in historic structures", "sports scores", "cooking recipes", "fashion designs"]'::jsonb,0,'Museums show engineering history.','original'),
('127.409.d.5.C',4,'A student wanting to learn about materials careers could contact a professional society such as:','["a poetry club", "ASM International", "a chess league", "a bakers guild"]'::jsonb,1,'Societies share career information.','original'),
('127.409.d.6.A',3,'Hooke''s law states that the stretch of a spring is proportional to the:','["color of spring", "price of spring", "force applied", "age of spring"]'::jsonb,2,'Extension is proportional to force within the elastic limit.','original'),
('127.409.d.6.A',4,'Which scientist''s laws of motion form the foundation of classical mechanics?','["Marie Curie", "Thomas Edison", "Albert Michelson", "Isaac Newton"]'::jsonb,3,'Newton''s laws describe force and motion.','original'),
('127.409.d.6.B',3,'The Bronze Age got its name from the alloy of copper and:','["tin", "lead", "gold", "zinc"]'::jsonb,0,'Bronze is copper alloyed with tin.','original'),
('127.409.d.6.B',4,'The Bessemer process made steel cheaper to produce by blowing air through molten iron to remove:','["sand only", "impurities", "tin", "gold"]'::jsonb,1,'It oxidized carbon and other impurities.','original'),
('127.409.d.6.C',3,'The shift from stone tools to bronze tools helped some societies gain advantages in farming and:','["swimming", "poetry", "warfare", "weather"]'::jsonb,2,'Better materials gave better tools and weapons.','original'),
('127.409.d.6.C',4,'Railroads of the 1800s expanded rapidly largely because affordable iron and steel rails became:','["invisible", "illegal", "unnecessary", "available"]'::jsonb,3,'Material supply shaped industrial growth.','original'),
('127.409.d.6.D',3,'Silicon semiconductors made possible modern:','["computers and phones", "horse carts", "wooden ships", "stone tools"]'::jsonb,0,'Electronics depend on semiconductors.','original'),
('127.409.d.6.D',4,'Lightweight composites in modern aircraft help improve:','["clothing size", "performance and efficiency", "flavor", "weather"]'::jsonb,1,'Lower weight saves fuel.','original'),
('127.409.d.6.E',3,'Roman builders used the arch because it carries loads mainly in:','["tension", "magnetism", "compression", "boredom"]'::jsonb,2,'Stone is strong in compression.','original'),
('127.409.d.6.E',4,'A dome spreads the weight of a roof outward and downward through its:','["paint", "color", "windows only", "curved shape"]'::jsonb,3,'Curvature guides loads to supports.','original'),
('127.409.d.7.A',3,'The length, width, and height of a block are examples of which kind of property?','["geometric", "material (intrinsic)", "musical", "chemical only"]'::jsonb,0,'Geometric properties describe size and shape.','original'),
('127.409.d.7.A',4,'Density and hardness are classified as:','["size properties", "material properties", "color properties", "geometric properties"]'::jsonb,1,'They depend on the substance, not the shape.','original'),
('127.409.d.7.B',3,'A tool that measures small outside dimensions to the nearest 0.001 inch is a:','["yardstick", "tape measure", "micrometer", "protractor"]'::jsonb,2,'Micrometers are high-precision gauges.','original'),
('127.409.d.7.B',4,'A vernier or dial caliper can measure a part''s outside diameter, inside diameter, and:','["color", "price", "age", "depth"]'::jsonb,3,'Calipers measure several dimensions.','original'),
('127.409.d.7.C',3,'To find the volume of a rectangular metal block, a student measures length, width, and height and then:','["multiplies them", "adds them", "ignores them", "subtracts them"]'::jsonb,0,'V = l x w x h.','original'),
('127.409.d.7.C',4,'A student measures a block 4 cm by 3 cm by 2 cm. Its volume is:','["9 cm3", "24 cm3", "12 cm3", "48 cm3"]'::jsonb,1,'4 x 3 x 2 = 24.','original'),
('127.409.d.7.D',3,'Scratching one mineral with another is a simple test of:','["mass", "price", "hardness", "color"]'::jsonb,2,'Harder materials scratch softer ones.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_64_v1'
from (values
('127.409.d.7.D',4,'A Rockwell test measures hardness by pressing an indenter into a material and measuring the:','["age of the sample", "sound of the press", "color of the dent", "depth of the dent"]'::jsonb,3,'Deeper dents mean softer material.','original'),
('127.409.d.7.E',3,'A metal block has mass 270 g and volume 100 cm3. Its density is:','["2.7 g/cm3", "27 g/cm3", "0.37 g/cm3", "170 g/cm3"]'::jsonb,0,'270 / 100 = 2.7.','original'),
('127.409.d.7.E',4,'A round rod has diameter 2 cm. Using A = pi r^2 with pi about 3.14, its cross-sectional area is about:','["6.28 cm2", "3.14 cm2", "12.56 cm2", "1.57 cm2"]'::jsonb,1,'r = 1 cm, so A = 3.14.','original'),
('127.409.d.7.F',3,'A material that can be drawn into a thin wire without breaking is:','["transparent", "brittle", "ductile", "magnetic"]'::jsonb,2,'Ductility is stretchability.','original'),
('127.409.d.7.F',4,'A material that can be hammered or rolled into thin sheets without cracking is:','["transparent", "fluid", "brittle", "malleable"]'::jsonb,3,'Malleability allows forming by compression.','original'),
('127.409.d.7.G',3,'Density does not change when you cut a piece of a material in half, so it is classified as an:','["intrinsic property", "extrinsic property", "optional property", "geometric property"]'::jsonb,0,'Intrinsic properties are independent of size.','original'),
('127.409.d.7.G',4,'The mass of a block changes when you cut it in half, so mass is an:','["unit", "extrinsic property", "material constant", "intrinsic property"]'::jsonb,1,'Extrinsic properties depend on amount or shape.','original'),
('127.409.d.7.H',3,'Plastics such as polyethylene belong to which material class?','["ceramics", "semiconductors only", "polymers", "metals"]'::jsonb,2,'Plastics are polymers.','original'),
('127.409.d.7.H',4,'Concrete reinforced with steel bars and fiberglass are examples of:','["liquids", "simple gases", "pure metals", "composite materials"]'::jsonb,3,'Composites combine two or more materials.','original'),
('127.409.d.8.A',3,'A force that acts along the long axis of a rod, pulling or pushing it, is called an:','["axial force", "radial force", "torsional force", "shear force"]'::jsonb,0,'Axial forces act along the axis.','original'),
('127.409.d.8.A',4,'Twisting a bolt with a wrench produces which kind of loading?','["normal only", "torsional", "axial", "radial"]'::jsonb,1,'Torsion twists a member.','original'),
('127.409.d.8.B',3,'A uniform load of 200 N per meter acting over a 5 m beam has a total force of:','["40 N", "10,000 N", "1,000 N", "205 N"]'::jsonb,2,'200 x 5 = 1,000.','original'),
('127.409.d.8.B',4,'Pressure is an example of a force distributed over:','["a color", "a point", "a second", "an area"]'::jsonb,3,'Pressure = force per area.','original'),
('127.409.d.8.C',3,'Three downward forces of 10 N, 20 N, and 30 N act on a beam. The combined single load is:','["60 N", "600 N", "20 N", "30 N"]'::jsonb,0,'10 + 20 + 30 = 60.','original'),
('127.409.d.8.C',4,'Two forces on a bar, 50 N upward and 20 N downward, combine to a net force of:','["30 N downward", "30 N upward", "1,000 N upward", "70 N upward"]'::jsonb,1,'50 - 20 = 30, upward.','original'),
('127.409.d.8.D',3,'A normal force on a surface acts:','["at random", "only upward", "perpendicular to the surface", "parallel to the surface"]'::jsonb,2,'Normal means perpendicular.','original'),
('127.409.d.8.D',4,'Scissors cutting paper apply which kind of force across the paper?','["magnetic force", "normal force", "gravity only", "shear force"]'::jsonb,3,'Shear acts parallel to a surface, sliding layers.','original'),
('127.409.d.8.E',3,'Axial stress equals the axial force divided by the:','["cross-sectional area", "color", "mass", "length"]'::jsonb,0,'Stress = force / area.','original'),
('127.409.d.8.E',4,'A 5,000 N pull on a rod with an area of 10 cm2 produces an axial stress of:','["5,000 N/cm2", "500 N/cm2", "50 N/cm2", "50,000 N/cm2"]'::jsonb,1,'5,000 / 10 = 500.','original'),
('127.409.d.9.A',3,'Railroad tracks have small gaps between rail sections because steel:','["melts at noon", "turns to wood", "expands when heated", "shrinks in sunlight"]'::jsonb,2,'Gaps allow for thermal expansion.','original'),
('127.409.d.9.A',4,'A bimetallic strip bends when heated because its two metals have different:','["prices", "names", "colors", "expansion rates"]'::jsonb,3,'Unequal expansion causes bending.','original'),
('127.409.d.9.B',3,'At the atomic level, heating a solid makes its atoms:','["vibrate with larger amplitude", "turn into liquid", "disappear", "stop moving"]'::jsonb,0,'Larger vibrations push atoms farther apart on average.','original'),
('127.409.d.9.B',4,'Thermal expansion is measurable because the average spacing between atoms:','["decreases as temperature rises", "increases as temperature rises", "becomes random", "never changes"]'::jsonb,1,'Spacing grows with heat.','original'),
('127.409.d.9.C',3,'A steel rod fixed rigidly between two walls and then heated can fail by buckling because expansion is:','["impossible", "unlimited", "constrained", "painted"]'::jsonb,2,'Constrained expansion creates large stress.','original'),
('127.409.d.9.C',4,'Moving parts such as pistons can seize if the parts expand until their clearance:','["improves", "becomes a color", "doubles", "disappears"]'::jsonb,3,'Zero clearance causes binding.','original'),
('127.409.d.9.D',3,'Expansion joints on a bridge deck allow the deck to:','["lengthen and shorten safely", "change color", "float", "stay frozen"]'::jsonb,0,'Joints absorb movement.','original'),
('127.409.d.9.D',4,'Concrete sidewalks are poured in sections with gaps or grooves to control cracking caused by:','["paint", "expansion and contraction", "sunlight color", "footsteps only"]'::jsonb,1,'Joints control where cracks form.','original'),
('127.409.d.9.E',3,'As the temperature of most metals rises toward melting, their strength generally:','["stays infinite", "doubles", "decreases", "increases"]'::jsonb,2,'Heat softens metals.','original'),
('127.409.d.9.E',4,'Some steels become more brittle at very low temperatures, which is why engineers consider the:','["paint color", "building''s address", "owner''s name", "operating temperature range"]'::jsonb,3,'Material choice depends on service conditions.','original'),
('127.409.d.10.A',3,'A tensile test specimen is often shaped like a dog bone so that failure occurs in the:','["narrow middle section", "label", "grips", "wide ends"]'::jsonb,0,'The reduced section concentrates stress.','original'),
('127.409.d.10.A',4,'A tensile testing machine pulls a specimen at a steady rate while recording the force and the:','["smell", "elongation", "age", "color"]'::jsonb,1,'Force and elongation give the stress-strain data.','original'),
('127.409.d.10.B',3,'Engineering stress is calculated as force divided by the specimen''s original:','["length", "color", "cross-sectional area", "mass"]'::jsonb,2,'Engineering stress uses the original area.','original'),
('127.409.d.10.B',4,'Engineering strain is the change in length divided by the:','["original mass", "final weight", "area", "original length"]'::jsonb,3,'Strain = change in length / original length.','original'),
('127.409.d.10.C',3,'On a stress-strain graph, stress is usually plotted on the:','["vertical axis", "time axis", "third axis", "horizontal axis"]'::jsonb,0,'Stress is the y-axis; strain is the x-axis.','original'),
('127.409.d.10.C',4,'A stress-strain plot of a material that returns to zero strain after unloading shows:','["corrosion", "elastic behavior", "plastic fracture", "melting"]'::jsonb,1,'Elastic strain is recoverable.','original'),
('127.409.d.10.D',3,'The straight, initial part of a stress-strain curve is the:','["fracture point", "necking region", "elastic region", "plastic region"]'::jsonb,2,'Stress is proportional to strain here.','original'),
('127.409.d.10.D',4,'The point where permanent deformation begins on a stress-strain curve is the:','["origin of the graph", "ultimate failure", "unit conversion", "yield point"]'::jsonb,3,'Past yield, deformation is plastic.','original'),
('127.409.d.10.E',3,'The highest stress on an engineering stress-strain curve is called the:','["ultimate tensile strength", "modulus", "elastic limit", "yield strength"]'::jsonb,0,'UTS is the maximum engineering stress.','original'),
('127.409.d.10.E',4,'The 0.2% offset method is used to estimate a material''s:','["melting point", "yield strength", "density", "color"]'::jsonb,1,'Offset lines locate yield for materials without a clear yield point.','original'),
('127.409.d.10.F',3,'Compared with a ductile metal, a brittle ceramic''s stress-strain curve typically shows:','["no stress", "long plastic region", "little plastic deformation before fracture", "large necking"]'::jsonb,2,'Brittle materials break suddenly.','original'),
('127.409.d.10.F',4,'A steeper initial slope on a stress-strain curve means the material is:','["hotter", "softer", "lighter", "stiffer"]'::jsonb,3,'Slope equals modulus of elasticity.','original'),
('127.409.d.10.G',3,'A concrete cylinder is usually tested in:','["compression", "bending only", "tension", "torsion"]'::jsonb,0,'Concrete is used mainly in compression.','original'),
('127.409.d.10.G',4,'A three-point bending test loads a beam by pushing at its middle while it rests on:','["a magnet", "two supports", "no supports", "one support"]'::jsonb,1,'Two outer supports and one center load.','original'),
('127.409.d.10.H',3,'In a three-point bending test, the maximum stress occurs near the beam''s:','["supports only", "paint", "outer surfaces at midspan", "ends"]'::jsonb,2,'Bending stress peaks at the outer fibers under the load.','original'),
('127.409.d.10.H',4,'A compression test on a short brittle block shows a sudden drop in load at the moment of:','["melting", "coloring", "rusting", "fracture"]'::jsonb,3,'The block crushes and carries less load.','original'),
('127.409.d.10.I',3,'Digital image correlation measures how a surface deforms by tracking a pattern of speckles in:','["camera images", "rulers", "radio signals", "sound waves"]'::jsonb,0,'DIC compares images before and after loading.','original'),
('127.409.d.10.I',4,'Compared with a single strain gauge, digital image correlation can show strain across:','["a single atom", "an entire surface", "one point only", "nothing"]'::jsonb,1,'DIC gives full-field data.','original'),
('127.409.d.11.A',3,'A rectangle 4 cm wide and 6 cm tall has an area of:','["48 cm2", "10 cm2", "24 cm2", "20 cm2"]'::jsonb,2,'4 x 6 = 24.','original'),
('127.409.d.11.A',4,'The second moment of area of a rectangle about its centroidal axis is I = b h^3 / 12. For b = 2 cm and h = 6 cm, I equals:','["72 cm4", "144 cm4", "18 cm4", "36 cm4"]'::jsonb,3,'2 x 216 / 12 = 36.','original'),
('127.409.d.11.B',3,'The parallel-axis theorem is used to find the second moment of area about an axis that is:','["parallel to the centroidal axis but offset", "at the origin only", "unrelated", "perpendicular to it"]'::jsonb,0,'It shifts I to a parallel axis.','original'),
('127.409.d.11.B',4,'In I = I_c + A d^2, the term d is the:','["density", "distance between the two parallel axes", "diameter of the bolt", "number of parts"]'::jsonb,1,'d is the offset distance.','original'),
('127.409.d.11.C',3,'To find the centroid of an L-shaped section, an engineer can divide it into simple shapes and compute a:','["sum of their ages", "sum of their colors", "weighted average of their centroids", "list of names"]'::jsonb,2,'Weights are the areas.','original'),
('127.409.d.11.C',4,'An I-beam is often analyzed by treating it as three rectangles and combining their areas and second moments using the:','["binomial theorem", "Pythagorean theorem", "ideal gas law", "parallel-axis theorem"]'::jsonb,3,'Composite shapes need axis shifts.','original'),
('127.409.d.11.D',3,'For a beam that resists bending, an I-shaped cross section is efficient because it puts material:','["far from the neutral axis", "at the neutral axis", "nowhere", "only at the center"]'::jsonb,0,'Material far from the axis adds the most stiffness.','original'),
('127.409.d.11.D',4,'A hollow tube resists twisting better than a solid rod of the same weight because material is placed:','["in a spiral only", "farther from the center", "in the air", "closer to the center"]'::jsonb,1,'Larger radius increases torsional stiffness.','original')
